def snapshot_recommendations(apps, schema_editor):
    alias = schema_editor.connection.alias
    benefit = apps.get_model('providers', 'Benefit')
    selection = apps.get_model('providers', 'FolderBenefit')
    today = timezone.localdate()
    current = benefit.objects.using(alias).filter(
        status='PUBLISHED', provider__status='PUBLISHED',
    ).filter(
        models.Q(valid_from__isnull=True) | models.Q(valid_from__lte=today),
        models.Q(valid_until__isnull=True) | models.Q(valid_until__gte=today),
    )
    legacy = apps.get_model('providers', 'FolderProvider')
    for row in legacy.objects.using(alias).iterator():
        selection.objects.using(alias).bulk_create([
            selection(collaborator_id=row.collaborator_id, benefit_id=pk)
            for pk in current.filter(provider_id=row.provider_id).values_list('pk', flat=True)
        ], ignore_conflicts=True)


